"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyInsightCards from "../beautiful-ui/primitives/InsightCards";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type InsightCardsProps = NonNullable<ComponentProps<typeof LegacyInsightCards>>;

export const InsightCards = forwardRef<HTMLDivElement, InsightCardsProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyInsightCards {...props} />
  </BeautifulUIRoot>
));

InsightCards.displayName = "InsightCards";

export default InsightCards;

"use client";

import { Liveline, type LivelinePoint, type LivelineSeries } from "liveline";
import { useEffect, useMemo, useState, type CSSProperties } from "react";
import { nestedRadius, useShape } from "@/lib/shape-context";
import "../beautiful-ui.css";

/* ─────────────────────────────────────────────────────────
 * INSIGHT CARDS
 * Embedded mini-visualizations in an "Insights N ‹ ›"
 * carousel. Autoplay yields as soon as a person uses it.
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16, 1, 0.3, 1)";

const formatPercent = (v: number) => `${v > 0 ? "+" : ""}${v.toFixed(2)}%`;
const formatMoney = (v: number) => `$${Math.round(v).toLocaleString("en-US")}`;
/* anchor the snapshot to *call* time (inside each card's mount-time memo) —
 * a module-load constant goes stale, and once the points age past the chart
 * window the canvas renders empty */
function makePoints(values: number[], gap = 6): LivelinePoint[] {
  const end = Math.floor(Date.now() / 1000);
  return values.map((value, index) => ({
    time: end - (values.length - 1 - index) * gap,
    value,
  }));
}

/* Catmull-Rom resample — turn a sparse series into a dense, smoothly curved
 * one so both the line and the hover cursor glide instead of stepping between
 * a handful of points. */
function smooth(values: number[], perSegment = 9): number[] {
  if (values.length < 3) return values.slice();
  const out: number[] = [];
  const n = values.length;
  for (let i = 0; i < n - 1; i += 1) {
    const p0 = values[Math.max(0, i - 1)];
    const p1 = values[i];
    const p2 = values[i + 1];
    const p3 = values[Math.min(n - 1, i + 2)];
    for (let s = 0; s < perSegment; s += 1) {
      const t = s / perSegment;
      const t2 = t * t;
      const t3 = t2 * t;
      out.push(
        0.5 *
          (2 * p1 +
            (-p0 + p2) * t +
            (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
            (-p0 + 3 * p1 - 3 * p2 + p3) * t3),
      );
    }
  }
  out.push(values[n - 1]);
  return out;
}

/* dense, smoothed points spanning exactly `spanSecs` — keeps the chart window
 * unchanged while multiplying the resolution. */
function smoothPoints(values: number[], spanSecs: number): LivelinePoint[] {
  const dense = smooth(values);
  return makePoints(dense, spanSecs / (dense.length - 1));
}

function useDarkMode() {
  const [dark, setDark] = useState(false);

  useEffect(() => {
    const root = document.documentElement;
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    const update = () =>
      setDark(
        root.classList.contains("dark") || (!root.classList.contains("light") && media.matches),
      );
    update();
    const observer = new MutationObserver(update);
    observer.observe(root, { attributes: true, attributeFilter: ["class"] });
    media.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media.removeEventListener("change", update);
    };
  }, []);

  return dark;
}

/* inline @entity mention */
function Entity({ name, tone }: { name: string; tone: string }) {
  return (
    <span className="inline-flex items-center gap-1 align-baseline font-medium text-[var(--ink)]">
      <span className={`inline-block size-2.5 rounded-full ${tone}`} />@{name}
    </span>
  );
}

function Mono({ children, tone }: { children: React.ReactNode; tone: "red" | "green" }) {
  return (
    <code
      className={`font-mono text-[12px] ${tone === "red" ? "text-[var(--red)]" : "text-[var(--green)]"}`}
    >
      {children}
    </code>
  );
}

function chartIndexFromPointer(event: React.PointerEvent<HTMLDivElement>, pointCount: number) {
  const rect = event.currentTarget.getBoundingClientRect();
  const progress = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
  return Math.round(progress * (pointCount - 1));
}

function ChartTooltip({ rows }: { rows: { label: string; value: string; color: string }[] }) {
  return (
    <div className="insight-chart-tooltip">
      {rows.map((row) => (
        <span key={row.label} className="insight-chart-tooltip-item">
          <span className="insight-chart-tooltip-dot" style={{ background: row.color }} />
          <span className="sr-only">{row.label}: </span>
          {row.value}
        </span>
      ))}
    </div>
  );
}

function moveChartCursor(
  event: React.KeyboardEvent<HTMLDivElement>,
  pointCount: number,
  current: number | null,
  setCurrent: (index: number | null) => void,
) {
  if (!["ArrowLeft", "ArrowRight", "Home", "End", "Escape"].includes(event.key)) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.key === "Escape") {
    setCurrent(null);
    return;
  }
  if (event.key === "Home") {
    setCurrent(0);
    return;
  }
  if (event.key === "End") {
    setCurrent(pointCount - 1);
    return;
  }
  const start = current ?? pointCount - 1;
  setCurrent(
    event.key === "ArrowRight" ? Math.min(pointCount - 1, start + 1) : Math.max(0, start - 1),
  );
}

/* 1 — return comparison: 2 series, legend + big deltas + line chart */
function CompareCard() {
  const dark = useDarkMode();
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const data = useMemo(
    () => ({
      mint: smoothPoints([-2.9, -3.4, -3.05, -3.86, -3.52, -4.1, -3.82, -4.41], 42),
      pistachio: smoothPoints([0.22, 0.58, 0.42, 0.91, 0.76, 1.08, 0.96, 1.15], 42),
    }),
    [],
  );

  const latestMint = data.mint.at(-1)?.value ?? -4.41;
  const latestPistachio = data.pistachio.at(-1)?.value ?? 1.15;
  const series: LivelineSeries[] = useMemo(
    () => [
      {
        id: "mint",
        label: "",
        data: data.mint,
        value: latestMint,
        color: "#f97316",
      },
      {
        id: "pistachio",
        label: "",
        data: data.pistachio,
        value: latestPistachio,
        color: "#3b82f6",
      },
    ],
    [data.mint, data.pistachio, latestMint, latestPistachio],
  );

  return (
    <div className="min-h-[278px] rounded-[var(--insight-card-radius)] bg-[var(--surface)] p-3 shadow-[var(--shadow-hairline)]">
      <div className="flex items-center gap-4">
        {[
          {
            name: "Mint Chip",
            delta: formatPercent(latestMint),
            sub: "-$2,377.66",
            tone: "red",
            dot: "bg-[var(--orange)]",
          },
          {
            name: "Pistachio",
            delta: formatPercent(latestPistachio),
            sub: "+$617.22",
            tone: "green",
            dot: "bg-[var(--bui-focus)]",
          },
        ].map((s) => (
          <div key={s.name} className="flex-1">
            <span className="flex items-center gap-1.5 text-[12px] text-[var(--ink-2)]">
              <span className={`size-2 rounded-full ${s.dot}`} />
              {s.name}
            </span>
            <span
              className={`block text-[16px] font-semibold tracking-[-0.01em] tabular-nums ${s.tone === "red" ? "text-[var(--red)]" : "text-[var(--green)]"}`}
            >
              {s.delta}
            </span>
            <Mono tone={s.tone as "red" | "green"}>{s.sub}</Mono>
          </div>
        ))}
      </div>
      <div className="mt-2 overflow-hidden rounded-[var(--insight-inset-radius)] bg-[var(--inset)] shadow-[var(--shadow-hairline)]">
        <div className="flex items-center justify-between border-b border-[var(--line)] px-2.5 py-1.5">
          <span className="text-[11px] text-[var(--ink-3)] tabular-nums">Trend snapshot</span>
          <span className="rounded-full bg-[var(--hover)] px-2 py-0.5 text-[11px] font-medium text-[var(--ink-2)]">
            Snapshot
          </span>
        </div>
        <div
          className="insight-chart-stage relative h-[166px]"
          role="group"
          tabIndex={0}
          aria-label="Mint Chip and Pistachio return trend. Use Left and Right Arrow keys to inspect values."
          onFocus={() => setHoverIndex(data.mint.length - 1)}
          onBlur={() => setHoverIndex(null)}
          onKeyDown={(event) => moveChartCursor(event, data.mint.length, hoverIndex, setHoverIndex)}
          onPointerDown={(event) => {
            event.currentTarget.focus();
            setHoverIndex(chartIndexFromPointer(event, data.mint.length));
          }}
          onClick={(event) => event.currentTarget.focus()}
          onPointerMove={(event) => setHoverIndex(chartIndexFromPointer(event, data.mint.length))}
          onPointerLeave={() => setHoverIndex(null)}
          onPointerCancel={() => setHoverIndex(null)}
          onPointerUp={() => setHoverIndex(null)}
        >
          <Liveline
            data={[]}
            value={0}
            series={series}
            theme={dark ? "dark" : "light"}
            grid={false}
            pulse={false}
            window={42}
            paused
            scrub={false}
            cursor="default"
            lineWidth={2.25}
            padding={{ top: 40, right: 0, bottom: 22, left: 0 }}
            formatValue={formatPercent}
          />
          {hoverIndex !== null && (
            <>
              <span
                className="insight-chart-cursor"
                style={{ left: `${(hoverIndex / (data.mint.length - 1)) * 100}%` }}
              />
              <span
                className="insight-chart-tooltip-anchor"
                style={{
                  left: `${Math.min(Math.max((hoverIndex / (data.mint.length - 1)) * 100, 28), 72)}%`,
                }}
              >
                <ChartTooltip
                  rows={[
                    {
                      label: "Mint Chip",
                      value: formatPercent(data.mint[hoverIndex].value),
                      color: "var(--orange)",
                    },
                    {
                      label: "Pistachio",
                      value: formatPercent(data.pistachio[hoverIndex].value),
                      color: "var(--bui-focus)",
                    },
                  ]}
                />
              </span>
            </>
          )}
          <dl className="sr-only">
            <dt>Mint Chip latest return</dt>
            <dd>{formatPercent(latestMint)}</dd>
            <dt>Pistachio latest return</dt>
            <dd>{formatPercent(latestPistachio)}</dd>
          </dl>
        </div>
      </div>
    </div>
  );
}

/* 2 — anomaly: bars with threshold + big spent value */
function AnomalyCard() {
  const dark = useDarkMode();
  const [metric, setMetric] = useState<"spend" | "usage">("spend");
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const spend = useMemo(() => makePoints([274, 289, 264, 307, 331, 1210, 1718, 2112], 7), []);
  const usage = useMemo(() => makePoints([18, 19, 17, 21, 22, 58, 81, 96], 7), []);

  const data = metric === "spend" ? spend : usage;
  const value = data.at(-1)?.value ?? (metric === "spend" ? 2112 : 96);
  const threshold = metric === "spend" ? "$2,112" : "82 kWh";
  const moneyLabel = formatMoney(spend.at(-1)?.value ?? 2112);

  return (
    <div className="min-h-[278px] rounded-[var(--insight-card-radius)] bg-[var(--surface)] p-3 shadow-[var(--shadow-hairline)]">
      <div className="flex items-center justify-between">
        <span className="flex items-center gap-1.5 text-[12px] font-medium text-[var(--ink)]">
          <svg
            width="12"
            height="12"
            viewBox="0 0 24 24"
            fill="none"
            stroke="var(--red)"
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M12 19V5M5 12l7-7 7 7" />
          </svg>
          High freezer spend
        </span>
        <span className="rounded-full bg-[var(--hover)] px-2 py-0.5 text-[11px] font-medium text-[var(--ink-2)]">
          Snapshot
        </span>
      </div>
      <div className="mt-2 overflow-hidden rounded-[var(--insight-inset-radius)] bg-[var(--inset)] shadow-[var(--shadow-hairline)]">
        <div className="flex items-center justify-between border-b border-[var(--line)] px-2.5 py-1.5">
          <span className="text-[11px] text-[var(--ink-3)] tabular-nums">
            {hoverIndex !== null
              ? metric === "spend"
                ? formatMoney(data[hoverIndex].value)
                : `${Math.round(data[hoverIndex].value)} kWh`
              : `${threshold} threshold`}
          </span>
          <span className="flex rounded-full bg-[var(--field)] p-0.5">
            {(["spend", "usage"] as const).map((item) => (
              <button
                key={item}
                type="button"
                aria-pressed={metric === item}
                onClick={() => setMetric(item)}
                className={`rounded-full px-2 py-0.5 text-[11px] font-medium transition-[background-color,color,box-shadow,transform] duration-160 active:scale-[0.98] ${
                  metric === item
                    ? "bg-[var(--surface)] text-[var(--ink)] shadow-[var(--shadow-btn)]"
                    : "text-[var(--ink-3)] hover:text-[var(--ink-2)]"
                }`}
              >
                {item === "spend" ? "Spend" : "Usage"}
              </button>
            ))}
          </span>
        </div>
        <div
          className="insight-chart-stage relative h-[166px]"
          role="group"
          tabIndex={0}
          aria-label={`${metric === "spend" ? "Freezer spend" : "Freezer usage"} trend. Use Left and Right Arrow keys to inspect values.`}
          onFocus={() => setHoverIndex(data.length - 1)}
          onBlur={() => setHoverIndex(null)}
          onKeyDown={(event) => moveChartCursor(event, data.length, hoverIndex, setHoverIndex)}
          onPointerDown={(event) => {
            event.currentTarget.focus();
            setHoverIndex(chartIndexFromPointer(event, data.length));
          }}
          onClick={(event) => event.currentTarget.focus()}
          onPointerMove={(event) => setHoverIndex(chartIndexFromPointer(event, data.length))}
          onPointerLeave={() => setHoverIndex(null)}
          onPointerCancel={() => setHoverIndex(null)}
          onPointerUp={() => setHoverIndex(null)}
        >
          <Liveline
            data={data}
            value={value}
            theme={dark ? "dark" : "light"}
            color="#ef4444"
            grid
            scrub={false}
            fill={false}
            pulse={false}
            momentum={false}
            paused
            window={49}
            lineWidth={2.25}
            cursor="crosshair"
            padding={{ top: 34, right: 0, bottom: 22, left: 0 }}
            formatValue={(v) => (metric === "spend" ? formatMoney(v) : `${Math.round(v)} kWh`)}
          />
          {hoverIndex !== null && (
            <>
              <span
                className="insight-chart-cursor"
                style={{ left: `${(hoverIndex / (data.length - 1)) * 100}%` }}
              />
              <span
                className="insight-chart-tooltip-anchor"
                style={{
                  left: `${Math.min(Math.max((hoverIndex / (data.length - 1)) * 100, 28), 72)}%`,
                }}
              >
                <ChartTooltip
                  rows={[
                    {
                      label: metric === "spend" ? "Spend" : "Usage",
                      value:
                        metric === "spend"
                          ? formatMoney(data[hoverIndex].value)
                          : `${Math.round(data[hoverIndex].value)} kWh`,
                      color: "var(--red)",
                    },
                  ]}
                />
              </span>
            </>
          )}
          <dl className="sr-only">
            <dt>Latest {metric === "spend" ? "spend" : "usage"}</dt>
            <dd>{metric === "spend" ? formatMoney(value) : `${Math.round(value)} kWh`}</dd>
            <dt>Threshold</dt>
            <dd>{threshold}</dd>
          </dl>
        </div>
      </div>
      <div className="mt-1.5 flex items-baseline gap-2">
        <span className="text-[16px] font-semibold tracking-[-0.01em] text-[var(--ink)] tabular-nums">
          {moneyLabel} spent
        </span>
        <Mono tone="red">+$1,834.66</Mono>
        <span className="text-[11px] text-[var(--ink-3)]">vs 3 months</span>
      </div>
    </div>
  );
}

/* 3 — allocation: hero number + segmented bar + legend */
function AllocationCard() {
  const segments = [
    {
      name: "VAN",
      label: "Vanilla",
      pct: 72.5,
      amount: "$51,785",
      cls: "bg-[var(--orange)]",
      tone: "text-[var(--orange)]",
    },
    {
      name: "CHOC",
      label: "Chocolate",
      pct: 22.8,
      amount: "$16,278",
      cls: "bg-[var(--line-strong)]",
      tone: "text-[var(--ink-2)]",
    },
    {
      name: "MINT",
      label: "Mint",
      pct: 4.7,
      amount: "$3,357",
      cls: "bg-[var(--line)]",
      tone: "text-[var(--ink-3)]",
    },
  ];
  const [selected, setSelected] = useState(segments[0].name);
  const active = segments.find((segment) => segment.name === selected) ?? segments[0];

  return (
    <div className="min-h-[278px] rounded-[var(--insight-card-radius)] bg-[var(--surface)] p-3 shadow-[var(--shadow-hairline)]">
      <span className="flex items-center gap-1.5 text-[12px] font-medium text-[var(--ink)]">
        <span className="flex size-3.5 items-center justify-center rounded-full bg-[var(--orange)] text-[8px] font-bold text-[var(--background)]">
          V
        </span>
        Vanilla allocation
      </span>
      <span className="mt-1 block text-[20px] font-semibold tracking-[-0.01em] text-[var(--ink)] tabular-nums">
        {active.amount}
      </span>
      <div
        className="mt-3 flex h-9 gap-0.5 overflow-hidden rounded-full bg-[var(--field)] p-0.5"
        role="group"
        aria-label="Allocation segments"
      >
        {segments.map((s) => (
          <button
            key={s.name}
            type="button"
            aria-pressed={selected === s.name}
            aria-label={`${s.label}: ${s.pct}%`}
            onClick={() => setSelected(s.name)}
            className={`relative h-full overflow-hidden rounded-full ${s.cls} transition-[opacity,transform,box-shadow] duration-240 active:scale-[0.98]`}
            style={{
              width: `${s.pct}%`,
              opacity: selected === s.name ? 1 : 0.58,
              boxShadow:
                selected === s.name
                  ? "inset 0 0 0 1px color-mix(in srgb, var(--foreground) 22%, transparent)"
                  : undefined,
              transitionTimingFunction: EASE,
            }}
          >
            <span
              className="absolute inset-y-1 left-1 rounded-full bg-foreground/20 transition-[width,opacity] duration-240"
              style={{
                width: selected === s.name ? "calc(100% - 8px)" : "0%",
                opacity: selected === s.name ? 1 : 0,
                transitionTimingFunction: EASE,
              }}
            />
          </button>
        ))}
      </div>
      <div className="mt-2 flex items-center gap-1.5">
        {segments.map((s) => (
          <button
            key={s.name}
            type="button"
            aria-pressed={selected === s.name}
            onClick={() => setSelected(s.name)}
            className={`flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[11px] transition-[background-color,color,transform] duration-160 active:scale-[0.98] ${
              selected === s.name
                ? "bg-[var(--field)] text-[var(--ink)]"
                : "text-[var(--ink-2)] hover:bg-[var(--hover)] hover:text-[var(--ink)]"
            }`}
          >
            <span className={`size-1.5 rounded-full ${s.cls}`} />
            {s.name} <span className="tabular-nums">{s.pct}%</span>
          </button>
        ))}
      </div>
      <div className="mt-3 min-h-16 rounded-[var(--insight-inset-radius)] bg-[var(--inset)] px-2.5 py-2 shadow-[var(--shadow-hairline)]">
        <span className={`block text-[12px] font-medium ${active.tone}`}>{active.label}</span>
        <span className="mt-1 block text-[11px] leading-relaxed text-[var(--ink-3)]">
          Contribution snapshot across current inventory value. Segment selection changes the
          inspected group without moving the card.
        </span>
      </div>
    </div>
  );
}

const PAGES = [
  {
    key: "compare",
    prose: (
      <>
        The worst performer in your <Entity name="Creamery" tone="bg-[var(--orange)]" /> is Rocky
        Road — down <Mono tone="red">-6%</Mono> or <Mono tone="red">-$2,453.44</Mono>.
      </>
    ),
    Card: CompareCard,
    pill: "Should I rebalance flavors?",
  },
  {
    key: "anomaly",
    prose: (
      <>
        Unusually high freezer bill on <span className="font-medium text-[var(--ink)]">Dec 13</span>{" "}
        — <Mono tone="red">+$1,834.66</Mono> above your average.
      </>
    ),
    Card: AnomalyCard,
    pill: "Get tips on cutting freezer costs",
  },
  {
    key: "allocation",
    prose: (
      <>
        You’re heavily invested in <Entity name="Vanilla" tone="bg-[var(--orange)]" /> — it’s{" "}
        <span className="font-medium text-[var(--ink)]">72.5%</span> of your case.
      </>
    ),
    Card: AllocationCard,
    pill: "If we look at seasonals, what changes?",
  },
];

export interface InsightCardsProps {
  initialPage?: number;
  onAction?: (action: string, page: number) => void;
}

export default function InsightCards({ initialPage = 0, onAction }: InsightCardsProps = {}) {
  const shape = useShape();
  const [page, setPage] = useState(Math.max(0, Math.min(PAGES.length - 1, initialPage)));

  const move = (direction: -1 | 1) => {
    setPage((current) => (current + direction + PAGES.length) % PAGES.length);
  };

  const { prose, Card, pill } = PAGES[page];

  return (
    <div
      className="min-h-[408px] w-full max-w-86"
      style={
        {
          "--insight-card-radius": `${shape.containerRadius}px`,
          // Every card uses p-3, so its inset surfaces sit 12px inside the edge.
          "--insight-inset-radius": `${nestedRadius(shape.containerRadius, 12)}px`,
        } as CSSProperties
      }
    >
      {/* pager header */}
      <div className="flex items-center justify-between">
        <span className="flex items-baseline gap-1.5">
          <span className="text-[13px] font-semibold text-[var(--ink)]">Insights</span>
          <span className="text-[13px] text-[var(--ink-3)] tabular-nums">{PAGES.length}</span>
        </span>
        <span className="flex items-center gap-0.5">
          {(["M15 18l-6-6 6-6", "M9 6l6 6-6 6"] as const).map((d, i) => (
            <button
              key={i}
              type="button"
              aria-label={i === 0 ? "Previous insight" : "Next insight"}
              onClick={() => move(i === 0 ? -1 : 1)}
              className={`flex size-6 items-center justify-center ${shape.variant === "pill" ? "rounded-full" : shape.button} text-[var(--ink-3)]
                transition-[background-color,color,transform] duration-80 hover:bg-[var(--hover)]
                hover:text-[var(--ink)] active:scale-[0.98]`}
            >
              <svg
                width="13"
                height="13"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d={d} />
              </svg>
            </button>
          ))}
        </span>
      </div>

      {/* page content — blurred crossfade */}
      <div
        aria-live="polite"
        className="transition-[opacity,filter] duration-240"
